mapper.select:
SELECT 
  FROM PHOTO_POSTS PP
  JOIN USERS U ON U.USER_ID = PP.CREATED_BY
  LEFT JOIN PHOTO_ALBUMS A ON A.ALBUM_ID = PP.ALBUM_ID
 WHERE PP.SCOPE_TYPE = #{scopeType}
   AND PP.SCOPE_ID = #{scopeId}

   AND PP.ALBUM_ID = #{albumId}

 ORDER BY PP.CREATED_AT DESC, PP.POST_ID DESC

SELECT * FROM (
    SELECT 
      FROM PHOTO_POSTS PP
      JOIN USERS U ON U.USER_ID = PP.CREATED_BY
      LEFT JOIN PHOTO_ALBUMS A ON A.ALBUM_ID = PP.ALBUM_ID
     WHERE PP.SCOPE_TYPE = #{scopeType}
       AND PP.SCOPE_ID = #{scopeId}
     ORDER BY PP.CREATED_AT DESC, PP.POST_ID DESC
) WHERE ROWNUM <= #{limit}

mapper.update:
UPDATE PHOTOS
   SET ALBUM_ID = #{albumId,jdbcType=NUMERIC}
 WHERE POST_ID = #{postId}
